field('REPRESENTATION_GATE',s['REPRESENTATION_GATE']);field('PART_GEOMETRY_GATE',s['PART_GEOMETRY_GATE']);field('CAN_START_REASSEMBLY_V2','YES' if s['CAN_START_REASSEMBLY_V2'] else 'NO');field('CAN_SCALE_TO_100_OBJECTS','NO');field('PRIMARY_REMAINING_BLOCKER',s['PRIMARY_REMAINING_BLOCKER']);field('NEXT_ALLOWED_STAGE',s['NEXT_ALLOWED_STAGE']);field('READ_ONLY_GUARD', 'PASS' if read(O/'integrity/READ_ONLY_GUARD.json')['pass'] else 'FAIL')
